/**
 * CJK 拼音转写引擎（CommonJS 版，零运行时依赖）
 *
 * 为 CJK 统一表意文字基本区（U+4E00..U+9FA5）提供完整拼音映射，数据以
 * Base64 编码的 16 位二进制查找表内嵌（约 54 KB）。
 *
 * 与 apps/cli 下的 pinyin.mjs 是同一份数据的两个模块形态：主进程是 CommonJS，
 * 因此单独提供 .cjs 版本；改动拼音数据时两处需同步。
 *
 * 数据布局：
 *   SYLLABLES    — 音节字典，下标 i 对应「编号 i+1」的音节
 *   PINYIN_DATA  — Base64 编码的 Uint16 数组，第 (码点 - 0x4E00) 项即该字的
 *                  音节编号；0 表示无拼音数据
 */

const SYLLABLES = ["a", "ai", "an", "ang", "ao", "ba", "bai", "ban", "bang", "bao", "bei", "ben", "beng", "bi", "bian", "biao", "bie", "bin", "bing", "bo", "bu", "ca", "cai", "can", "cang", "cao", "ce", "cen", "ceng", "cha", "chai", "chan", "chang", "chao", "che", "chen", "cheng", "chi", "chong", "chou", "chu", "chua", "chuai", "chuan", "chuang", "chui", "chun", "chuo", "ci", "cong", "cou", "cu", "cuan", "cui", "cun", "cuo", "da", "dai", "dan", "dang", "dao", "de", "den", "deng", "di", "dian", "diao", "die", "ding", "diu", "dong", "dou", "du", "duan", "dui", "dun", "duo", "e", "ei", "en", "eng", "er", "fa", "fan", "fang", "fei", "fen", "feng", "fiao", "fo", "fou", "fu", "ga", "gai", "gan", "gang", "gao", "ge", "gei", "gen", "geng", "gong", "gou", "gu", "gua", "guai", "guan", "guang", "gui", "gun", "guo", "ha", "hai", "han", "hang", "hao", "he", "hei", "hen", "heng", "hm", "hong", "hou", "hu", "hua", "huai", "huan", "huang", "hui", "hun", "huo", "ji", "jia", "jian", "jiang", "jiao", "jie", "jin", "jing", "jiong", "jiu", "ju", "juan", "jue", "jun", "ka", "kai", "kan", "kang", "kao", "ke", "ken", "keng", "kong", "kou", "ku", "kua", "kuai", "kuan", "kuang", "kui", "kun", "kuo", "la", "lai", "lan", "lang", "lao", "le", "lei", "leng", "li", "lia", "lian", "liang", "liao", "lie", "lin", "ling", "liu", "lo", "long", "lou", "lu", "luan", "lun", "luo", "lv", "lve", "m", "ma", "mai", "man", "mang", "mao", "me", "mei", "men", "meng", "mi", "mian", "miao", "mie", "min", "ming", "miu", "mo", "mou", "mu", "n", "na", "nai", "nan", "nang", "nao", "ne", "nei", "nen", "neng", "ni", "nian", "niang", "niao", "nie", "nin", "ning", "niu", "nong", "nou", "nu", "nuan", "nun", "nuo", "nv", "nve", "o", "ou", "pa", "pai", "pan", "pang", "pao", "pei", "pen", "peng", "pi", "pian", "piao", "pie", "pin", "ping", "po", "pou", "pu", "qi", "qia", "qian", "qiang", "qiao", "qie", "qin", "qing", "qiong", "qiu", "qu", "quan", "que", "qun", "ran", "rang", "rao", "re", "ren", "reng", "ri", "rong", "rou", "ru", "rua", "ruan", "rui", "run", "ruo", "sa", "sai", "san", "sang", "sao", "se", "sen", "seng", "sha", "shai", "shan", "shang", "shao", "she", "shen", "sheng", "shi", "shou", "shu", "shua", "shuai", "shuan", "shuang", "shui", "shun", "shuo", "si", "song", "sou", "su", "suan", "sui", "sun", "suo", "ta", "tai", "tan", "tang", "tao", "te", "teng", "ti", "tian", "tiao", "tie", "ting", "tong", "tou", "tu", "tuan", "tui", "tun", "tuo", "wa", "wai", "wan", "wang", "wei", "wen", "weng", "wo", "wu", "xi", "xia", "xian", "xiang", "xiao", "xie", "xin", "xing", "xiong", "xiu", "xu", "xuan", "xue", "xun", "ya", "yan", "yang", "yao", "ye", "yi", "yin", "ying", "yo", "yong", "you", "yu", "yuan", "yue", "yun", "za", "zai", "zan", "zang", "zao", "ze", "zei", "zen", "zeng", "zha", "zhai", "zhan", "zhang", "zhao", "zhe", "zhen", "zheng", "zhi", "zhong", "zhou", "zhu", "zhua", "zhuai", "zhuan", "zhuang", "zhui", "zhun", "zhuo", "zi", "zong", "zou", "zu", "zuan", "zui", "zun", "zuo"]
const PINYIN_DATA = ''

// 惰性解码：首次调用时才解 Base64，未用到拼音时不必白付 54 KB 的解码开销
let table = null

/**
 * 解码并缓存拼音查找表。
 *
 * Node 环境优先用 Buffer；其他环境（浏览器）回退到 atob + 手动逐字节转换。
 * 解出的字节流按 16 位无符号整数视图解释，零拷贝映射为 Uint16Array。
 * @returns {Uint16Array}
 */
function getTable() {
  if (!table) {
    let buf
    if (typeof Buffer !== 'undefined') {
      buf = Buffer.from(PINYIN_DATA, 'base64')
    } else {
      // 非 Node 环境：atob 得到二进制字符串，再逐字节搬进 Uint8Array
      const bin = atob(PINYIN_DATA)
      const u8 = new Uint8Array(bin.length)
      for (let i = 0; i < bin.length; i++) {
        u8[i] = bin.charCodeAt(i)
      }
      buf = u8
    }
    table = new Uint16Array(buf.buffer, buf.byteOffset, buf.byteLength / 2)
  }
  return table
}

/**
 * 取单个汉字的拼音（不带声调）。
 * 仅覆盖基本区 U+4E00..U+9FA5；非汉字或表内编号越界时返回 null。
 * @param {string} char - 单个字符
 * @returns {string|null}
 */
function getCharPinyin(char) {
  if (!char) return null
  const code = char.codePointAt(0)
  if (code >= 0x4e00 && code <= 0x9fa5) {
    const t = getTable()
    // 表内以「码点偏移」为下标，存的音节编号从 1 开始（0 表示无数据）
    const idx = t[code - 0x4e00]
    if (idx > 0 && idx <= SYLLABLES.length) {
      return SYLLABLES[idx - 1]
    }
  }
  return null
}

/**
 * 把中文文本转写为以 "-" 连接的 ASCII 片段序列。
 *
 * 处理规则：
 *   - 有拼音数据的汉字 → 其拼音
 *   - 基本区之外的 CJK 字符（无拼音数据）→ `u<十六进制码点>`，保证唯一且可逆
 *   - 其余字符（字母 / 数字 / 符号）→ 原样累积，遇中文边界时整段推出
 * @param {string} text
 * @returns {string}
 */
function transliterateChinese(text) {
  if (!text) return ''
  // 用 Array.from 而非 split('')，保证代理对（emoji 等）不被拆坏
  const chars = Array.from(String(text))
  const parts = []
  // 累积连续的非中文片段，遇中文时一次性推出，避免逐字符产生多余分隔符
  let asciiBuf = ''

  for (const ch of chars) {
    const py = getCharPinyin(ch)
    if (py) {
      if (asciiBuf) {
        parts.push(asciiBuf)
        asciiBuf = ''
      }
      parts.push(py)
    } else if (/[\u3400-\u9fff]/u.test(ch)) {
      // 扩展区汉字：无拼音数据，用码点占位，避免整段丢失
      if (asciiBuf) {
        parts.push(asciiBuf)
        asciiBuf = ''
      }
      parts.push(`u${ch.codePointAt(0).toString(16)}`)
    } else {
      asciiBuf += ch
    }
  }
  if (asciiBuf) {
    parts.push(asciiBuf)
  }
  return parts.join('-')
}

/**
 * 生成可安全用作目录名 / 文件名的 slug。
 *
 * 步骤：转写中文 → NFKD 归一化并剥离变音符号 → 非字母数字一律替换为 "-"
 * → 去掉首尾连字符 → 转小写 → 截断到 48 字符（避免超长路径）。
 * @param {string} text
 * @returns {string}
 */
function safeTaskSlug(text) {
  const transliterated = transliterateChinese(text || 'art-text')
  const slug = transliterated
    // NFKD 把带音标的拉丁字母拆成「基字母 + 组合符号」，下一行再剥掉组合符号
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .toLowerCase()
  return (slug || 'art-text').slice(0, 48)
}

module.exports = {
  SYLLABLES,
  getTable,
  getCharPinyin,
  transliterateChinese,
  safeTaskSlug,
}
